#!/usr/bin/env node
/**
 * GF-03 / S2: `pnpm kyberion resolve generated` — regenerate every committed,
 * drift-checked generated artifact in dependency order and stage the results,
 * so no derived file is ever regenerated by hand.
 *
 * Use it after a merge/rebase, or whenever a freshness gate reports drift. It
 * works with or without the optional "kyberion-regenerate" merge driver: an
 * unmerged generated file is first rebuilt from its index conflict stages with
 * the driver's own strategy (`git_merge_regenerate.mjs --from-index`), so
 * env-registry.json gets the entry-by-name merge either way.
 *
 * GENERATED_ARTIFACT_STEPS is the single catalog: each step names its
 * generator script, the tracked outputs it stages and the steps it must run
 * after (`after`). `resolve_generated.test.ts` keeps it in sync with the
 * generator `--check` gates in ci-gates.json and with `.gitattributes`.
 * Changelog fragments are validated only — assembling them into CHANGELOG.md
 * is a release step (scripts/assemble_changelog.ts).
 *
 * Flags: --check (no writes; lists every drifted file; exit 1 on drift),
 * --no-stage (write, do not `git add`), --fast (skip `slow` steps; CI still
 * runs them). The `.husky/pre-push` hook runs `--check --fast`;
 * KYBERION_SKIP_PRE_PUSH=1 skips that hook for one push.
 */
import * as path from 'node:path';
import { pathResolver } from '@agent/core/path-resolver';
import { safeExecResult } from '@agent/core/secure-io';
import {
  clearProcessExitCode,
  defineScript,
  getProcessExitCode,
  isDirectScript,
  ScriptExitError,
} from './lib/harness.js';
import { guardCliArgs, type CliGuardSpec } from './lib/cli-guard.js';

/** The one command that regenerates (or, with --check, verifies) every generated file. */
export const RESOLVE_GENERATED_COMMAND = 'pnpm kyberion resolve generated';
/** Env flag the `.husky/pre-push` hook honours to skip its drift check for one push. */
export const PRE_PUSH_SKIP_ENV = 'KYBERION_SKIP_PRE_PUSH';

export interface GeneratedArtifactStep {
  id: string;
  /** Generator entry (repo-relative); its `--check` mode is what the CI gate runs. */
  script: string;
  /**
   * Committed outputs: exact repo-relative paths, or directory prefixes ending
   * in `/`. Only these are staged, and only their drift fails `--check`
   * (provider-hooks also writes gitignored provider state CI never sees).
   */
  tracked: string[];
  /** Tracked outputs also carry `merge=kyberion-regenerate` in .gitattributes. */
  mergeDriver?: boolean;
  /** Step ids whose outputs this generator reads; they must run first. */
  after?: string[];
  run(argv: string[]): Promise<unknown>;
  /** Validation-only steps always run with `--check`. */
  checkOnly?: boolean;
  /** Write passes needed to reach a fixed point (default 1). */
  passes?: number;
  /** Too slow for the pre-push hook; `--fast` skips it (its CI gate still runs). */
  slow?: boolean;
}

