/** Problems with the step ids or order (empty when the catalog is sound). */
export function validateStepOrder(steps: readonly GeneratedArtifactStep[]): string[] {
  const problems: string[] = [];
  const seen = new Set<string>();
  const ids = new Set(steps.map((step) => step.id));
  for (const step of steps) {
    if (seen.has(step.id)) problems.push(`duplicate step id ${step.id}`);
    for (const dependency of step.after ?? []) {
      if (!ids.has(dependency)) problems.push(`${step.id} runs after unknown step ${dependency}`);
      else if (!seen.has(dependency)) problems.push(`${step.id} must run after ${dependency}`);
    }
    seen.add(step.id);
  }
  return problems;
}

/** Repo-relative, `/`-separated form of a generator output path. */
export function toRepoRelative(filePath: string, rootDir: string): string {
  return path.relative(rootDir, path.resolve(rootDir, filePath)).split(path.sep).join('/');
}

export function isTrackedOutput(relativePath: string, tracked: readonly string[]): boolean {
  return tracked.some((entry) =>
    entry.endsWith('/') ? relativePath.startsWith(entry) : relativePath === entry
  );
}

/**
 * The `changed` or `files` list a defineGenerator run returns, as sorted
 * repo-relative paths limited to the step's tracked outputs; undefined when
 * the run returned no such list (it threw, or is not a generator).
 */
export function trackedGeneratorPaths(
  result: unknown,
  key: 'changed' | 'files',
  tracked: readonly string[],
  rootDir: string
): string[] | undefined {
  if (typeof result !== 'object' || result === null) return undefined;
  const value = (result as Record<string, unknown>)[key];
  if (!Array.isArray(value)) return undefined;
  return value
    .map((entry: unknown) => {
      if (typeof entry === 'string') return entry;
      if (typeof entry === 'object' && entry !== null && 'path' in entry) {
        const filePath = (entry as { path: unknown }).path;
        return typeof filePath === 'string' ? filePath : '';
      }
      return '';
    })
    .filter((entry) => entry !== '')
    .map((entry) => toRepoRelative(entry, rootDir))
    .filter((entry) => isTrackedOutput(entry, tracked))
    .sort();
}

export interface ResolveGeneratedResult {
  /** Step ids that drifted (check) or failed to generate (write). */
  failed: string[];
  /** Tracked files that are out of date (check mode). */
  drifted: string[];
  staged: string[];
  /** Slow step ids skipped by `fast`. */
  skipped: string[];
}

export async function resolveGeneratedArtifacts(
  options: { check: boolean; stage: boolean; fast?: boolean; rootDir?: string },
  steps: readonly GeneratedArtifactStep[] = GENERATED_ARTIFACT_STEPS
): Promise<ResolveGeneratedResult> {
  const rootDir = options.rootDir ?? pathResolver.rootDir();
  const failed: string[] = [];
  const drifted: string[] = [];
  const staged: string[] = [];
  const skipped: string[] = [];
  for (const step of steps) {
    if (options.fast && step.slow) {
      skipped.push(step.id);
      continue;
    }
    const checking = options.check || step.checkOnly === true;
    const passes = checking ? 1 : (step.passes ?? 1);
    let code: number | undefined;
    let result: unknown;
    for (let pass = 0; pass < passes && !code; pass += 1) {
      clearProcessExitCode();
      result = await step.run(checking ? ['--check', '--quiet'] : ['--quiet']);
      code = getProcessExitCode();
      clearProcessExitCode();
    }
    if (code !== undefined && code !== 0) {
      const changed = checking
        ? trackedGeneratorPaths(result, 'changed', step.tracked, rootDir)
        : undefined;
      // Drift confined to untracked outputs (gitignored provider state) is
      // invisible to CI; an error or tracked drift fails the step.
      if (changed !== undefined && changed.length === 0 && step.tracked.length > 0) continue;
      failed.push(step.id);
      if (changed) drifted.push(...changed);
      continue;
    }
    if (!options.check && options.stage) {
      const written = trackedGeneratorPaths(result, 'files', step.tracked, rootDir);
      staged.push(...(written ?? step.tracked.filter((entry) => !entry.endsWith('/'))));
    }
  }
  return { failed, drifted, staged, skipped };
}

/** Message for a failed run; check mode always names the exact fix command. */
export function formatResolveFailure(
  check: boolean,
  failed: readonly string[],
  drifted: readonly string[]
): string {
  if (!check) {
    return `generation failed: ${failed.join(', ')} (rerun the generator directly for details)`;
  }
  const files = drifted.map((file) => `\n  - ${file}`).join('');
  return (
    `generated artifacts out of date: ${failed.join(', ')}${files}\n` +
    `fix: run \`${RESOLVE_GENERATED_COMMAND}\` and commit the result`
  );
}

function git(args: string[]): { status: number | null; stdout: string; stderr: string } {
  return safeExecResult('git', args, { cwd: pathResolver.rootDir(), timeoutMs: 60_000 });
}

/** Generated paths git still lists as unmerged (a merge without the driver). */
export function unmergedGeneratedPaths(
  unmergedOutput: string,
  steps: readonly GeneratedArtifactStep[] = GENERATED_ARTIFACT_STEPS
): string[] {
  const tracked = steps.flatMap((step) => step.tracked);
  return unmergedOutput
    .split(/\r?\n/u)
    .map((line) => line.trim())
    .filter((line) => line !== '' && isTrackedOutput(line, tracked));
}

/**
 * Replace conflict markers in unmerged generated files with the merge
 * driver's strategy, computed from the index stages (:1: base, :2: ours,
 * :3: theirs) — so the optional driver is never required. Returns the paths
 * that still need a human (curated env-registry conflicts).
 */
function resolveUnmergedFromIndex(paths: readonly string[]): string[] {
  const unresolved: string[] = [];
  for (const filePath of paths) {
    const result = safeExecResult(
      process.execPath,
      [pathResolver.rootResolve('scripts/git_merge_regenerate.mjs'), '--from-index', filePath],
      { cwd: pathResolver.rootDir(), timeoutMs: 60_000 }
    );
    if (result.status !== 0) unresolved.push(filePath);
  }
  return unresolved;
}

export const DRIVER_HINT =
  'hint: optional merge driver not installed — the repository owner can run `pnpm kyberion resolve install-driver` once so merges keep generated files free of conflict markers.';

function driverInstalled(): boolean | undefined {
  const inside = git(['rev-parse', '--is-inside-work-tree']);
  if (inside.status !== 0) return undefined;
  return git(['config', '--get', 'merge.kyberion-regenerate.driver']).stdout.trim() !== '';
}

function stagePaths(paths: readonly string[]): void {
  if (paths.length === 0) return;
  const result = git(['add', '--', ...paths]);
  if (result.status !== 0) {
    throw new ScriptExitError(1, `git add failed: ${result.stderr || result.stdout}`);
  }
}

/** CU-01: `--help` / typos exit before any generator runs or anything is staged. */
export const RESOLVE_GENERATED_CLI: CliGuardSpec = {
  command: RESOLVE_GENERATED_COMMAND,
  manifestId: 'script.resolve.generated',
  options: [
    { flag: '--check' },
    { flag: '--no-stage' },
    { flag: '--fast' },
    { flag: '--json' },
    { flag: '--quiet' },
  ],
};

export const main = defineScript({
  name: 'resolve:generated',
  flags: ['check', 'json', 'quiet'],
  async run(context) {
    if (guardCliArgs(context.argv, RESOLVE_GENERATED_CLI, context.print)) return undefined;
    const stage = !context.argv.includes('--no-stage');
    const installed = driverInstalled();
    if (installed === false && !context.json && !context.check) context.print(DRIVER_HINT);
    const unmerged = unmergedGeneratedPaths(git(['diff', '--name-only', '--diff-filter=U']).stdout);
    const needsHuman = context.check ? unmerged : resolveUnmergedFromIndex(unmerged);
    if (needsHuman.length > 0) {
      throw new ScriptExitError(
        1,
        context.check
          ? `generated files are still unmerged: ${needsHuman.join(', ')} (run ${RESOLVE_GENERATED_COMMAND})`
          : `unmerged generated files need a manual resolution first: ${needsHuman.join(', ')} ` +
              '(env-registry.json: keep both sides of each conflicting entry, then rerun)'
      );
    }
    const { failed, drifted, staged, skipped } = await resolveGeneratedArtifacts({
      check: context.check,
      stage,
      fast: context.argv.includes('--fast'),
    });
    if (failed.length === 0) stagePaths(staged);
    const summary = {
      ok: failed.length === 0,
      mode: context.check ? 'check' : 'write',
      driver_installed: installed ?? null,
      resolved_from_index: context.check ? [] : unmerged,
      steps: GENERATED_ARTIFACT_STEPS.map((step) => step.id),
      skipped,
      failed,
      drifted,
      staged: failed.length === 0 ? staged : [],
    };
    context.print(summary);
    if (failed.length > 0) {
      throw new ScriptExitError(1, formatResolveFailure(context.check, failed, drifted));
    }
    return summary;
  },
});

if (
  isDirectScript(import.meta.url, 'resolve_generated.ts') ||
  isDirectScript(import.meta.url, 'resolve_generated.js')
)
  void main();
